window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d92f99d928ee5d95"]={"versions": [{"id": "FIG-d92f99d928ee5d95", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Sicherheits-Metamodells im Kontext des Intrusion Detection System Manager (IdsM). Das Diagramm definiert die Konfigurationsstruktur von <code>IdsmProperties</code> und <code>IdsmInstance</code> sowie deren Assoziationen zu Filtermechanismen (<code>IdsmTrafficLimitation</code> und <code>IdsmRateLimitation</code>) innerhalb des Templates <code>AUTOSAR_TPS_SecurityExtractTemplate</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>IdsmProperties</strong>: Spezialisierung von <code>IdsCommonElement</code>. Dient als Aggregationsbehälter und besitzt Kompositionsbeziehungen:</li>\n<li><code>+trafficLimitationFilter</code> [0..*] zu <code>IdsmTrafficLimitation</code></li>\n<li><code>+rateLimitationFilter</code> [0..*] zu <code>IdsmRateLimitation</code></li>\n<li><strong>AbstractSecurityIdsmInstanceFilter</strong>: Abstrakte Basisklasse, spezialisiert von <code>Identifiable</code>. Bildet die Generalisierung für die konkreten Filterklassen:</li>\n<li><code>IdsmTrafficLimitation</code>: Erbt von <code>AbstractSecurityIdsmInstanceFilter</code>. Attribute: <code>+maxBytesInInterval: PositiveInteger [0..1]</code>, <code>+timeInterval: Float [0..1]</code>.</li>\n<li><code>IdsmRateLimitation</code>: Erbt von <code>AbstractSecurityIdsmInstanceFilter</code>. Attribute: <code>+maxEventsInInterval: PositiveInteger</code>, <code>+timeInterval: Float</code>.</li>\n<li><strong>IdsmInstance</strong>: Spezialisierung von <code>IdsCommonElement</code>. Attribute: <code>+idsmInstanceId: PositiveInteger [0..1]</code>, <code>+timestampFormat: String [0..1]</code>. Referenziert Filterinstanzen über gerichtete Assoziationen:</li>\n<li><code>+trafficLimitationFilter</code> [0..1] zu <code>IdsmTrafficLimitation</code> (stereotypisiert mit <code>«atpVariation»</code>)</li>\n<li><code>+rateLimitationFilter</code> [0..1] zu <code>IdsmRateLimitation</code> (stereotypisiert mit <code>«atpVariation»</code>)</li>\n<li><strong>Variation Annotation</strong>: Zugeordnete <code>«atpVariation» Tags</code> mit <code>atp.Status = draft</code> und <code>vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablaufsemantik. Das Zusammenspiel beschreibt die Konfigurationsbindung: Zur Laufzeit bzw. Verarbeitungszeit aggregiert eine <code>IdsmInstance</code> über optionale Assoziationen Filterprofile (<code>IdsmTrafficLimitation</code> zur Begrenzung von Byte-Mengen pro Zeitintervall und <code>IdsmRateLimitation</code> zur Begrenzung der Ereignisanzahl pro Zeitintervall), welche zentral unter <code>IdsmProperties</code> definiert und verwaltet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Filterzuordnungen von <code>IdsmInstance</code> zu den jeweiligen Limitation-Filtern unterliegen dem AUTOSAR-Variantenhandling (<code>«atpVariation»</code>) mit Status <code>draft</code> und spätestem Bindezeitpunkt <code>preCompileTime</code>. Filterdefinitionen unter <code>IdsmProperties</code> sind als Kompositionen (0..*) multipel konfigurierbar, während eine konkrete <code>IdsmInstance</code> jeweils maximal einen <code>rateLimitationFilter</code> (0..1) und einen <code>trafficLimitationFilter</code> (0..1) referenzieren kann. Attributwerte für <code>IdsmRateLimitation</code> sind verpflichtend, während sie bei <code>IdsmTrafficLimitation</code> und <code>IdsmInstance</code> optional ([0..1]) modelliert sind.</p>"}, {"id": "FIG-48a50837da86699a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Sicherheits-Metamodells im Kontext des Intrusion Detection System Manager (IdsM). Das Diagramm definiert die Konfigurationsstruktur von <code>IdsmProperties</code> und <code>IdsmInstance</code> sowie deren Assoziationen zu Filtermechanismen (<code>IdsmTrafficLimitation</code> und <code>IdsmRateLimitation</code>) innerhalb des Templates <code>AUTOSAR_TPS_SecurityExtractTemplate</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>IdsmProperties</strong>: Spezialisierung von <code>IdsCommonElement</code>. Dient als Aggregationsbehälter und besitzt Kompositionsbeziehungen:</li>\n<li><code>+trafficLimitationFilter</code> [0..*] zu <code>IdsmTrafficLimitation</code></li>\n<li><code>+rateLimitationFilter</code> [0..*] zu <code>IdsmRateLimitation</code></li>\n<li><strong>AbstractSecurityIdsmInstanceFilter</strong>: Abstrakte Basisklasse, spezialisiert von <code>Identifiable</code>. Bildet die Generalisierung für die konkreten Filterklassen:</li>\n<li><code>IdsmTrafficLimitation</code>: Erbt von <code>AbstractSecurityIdsmInstanceFilter</code>. Attribute: <code>+maxBytesInInterval: PositiveInteger [0..1]</code>, <code>+timeInterval: Float [0..1]</code>.</li>\n<li><code>IdsmRateLimitation</code>: Erbt von <code>AbstractSecurityIdsmInstanceFilter</code>. Attribute: <code>+maxEventsInInterval: PositiveInteger</code>, <code>+timeInterval: Float</code>.</li>\n<li><strong>IdsmInstance</strong>: Spezialisierung von <code>IdsCommonElement</code>. Attribute: <code>+idsmInstanceId: PositiveInteger [0..1]</code>, <code>+timestampFormat: String [0..1]</code>. Referenziert Filterinstanzen über gerichtete Assoziationen:</li>\n<li><code>+trafficLimitationFilter</code> [0..1] zu <code>IdsmTrafficLimitation</code> (stereotypisiert mit <code>«atpVariation»</code>)</li>\n<li><code>+rateLimitationFilter</code> [0..1] zu <code>IdsmRateLimitation</code> (stereotypisiert mit <code>«atpVariation»</code>)</li>\n<li><strong>Variation Annotation</strong>: Zugeordnete <code>«atpVariation» Tags</code> mit <code>atp.Status = draft</code> und <code>vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Ablaufsemantik. Das Zusammenspiel beschreibt die Konfigurationsbindung: Zur Laufzeit bzw. Verarbeitungszeit aggregiert eine <code>IdsmInstance</code> über optionale Assoziationen Filterprofile (<code>IdsmTrafficLimitation</code> zur Begrenzung von Byte-Mengen pro Zeitintervall und <code>IdsmRateLimitation</code> zur Begrenzung der Ereignisanzahl pro Zeitintervall), welche zentral unter <code>IdsmProperties</code> definiert und verwaltet werden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Filterzuordnungen von <code>IdsmInstance</code> zu den jeweiligen Limitation-Filtern unterliegen dem AUTOSAR-Variantenhandling (<code>«atpVariation»</code>) mit Status <code>draft</code> und spätestem Bindezeitpunkt <code>preCompileTime</code>. Filterdefinitionen unter <code>IdsmProperties</code> sind als Kompositionen (0..*) multipel konfigurierbar, während eine konkrete <code>IdsmInstance</code> jeweils maximal einen <code>rateLimitationFilter</code> (0..1) und einen <code>trafficLimitationFilter</code> (0..1) referenzieren kann. Attributwerte für <code>IdsmRateLimitation</code> sind verpflichtend, während sie bei <code>IdsmTrafficLimitation</code> und <code>IdsmInstance</code> optional ([0..1]) modelliert sind.</p>"}], "trans": [{"from": "FIG-d92f99d928ee5d95", "to": "FIG-48a50837da86699a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
